mapper.insert:
INSERT INTO observation (incident_id, investigation_id, recovery_verification_id, capability_invocation_id,
                         managed_resource_id, observation_kind, schema_name, schema_version, payload,
                         summary, observed_at, window_start, window_end, created_at)
SELECT #{o.incidentId}, #{o.investigationId}, #{o.recoveryVerificationId}, ci.id, #{o.managedResourceId},
       #{o.observationKind}, #{o.schemaName}, #{o.schemaVersion}, #{o.payload}, #{o.summary},
       #{o.observedAt}, #{o.windowStart}, #{o.windowEnd}, #{o.createdAt}
FROM capability_invocation ci
WHERE ci.id = #{o.capabilityInvocationId}
  AND ci.status = 'SUCCEEDED'
  AND ci.incident_id = #{o.incidentId}
  AND ci.managed_resource_id = #{o.managedResourceId}
  AND ci.investigation_id <=> #{o.investigationId}
  AND ci.recovery_verification_id <=> #{o.recoveryVerificationId}
